Flutter Code (Front-end):

First, you need to create a Flutter app that allows users to send voice commands to the Firebase Cloud Functions. Here's an example code that shows how to create a Flutter app that uses the speech\_to\_text package to capture voice commands:
```dart
import 'package:flutter/material.dart';
import 'package:speech_to_text/speech_to_text.dart' as stt;

class MyHomePage extends StatefulWidget {
  @override
  _MyHomePageState createState() => _MyHomePageState();
}

class _MyHomePageState extends State<MyHomePage> {
  stt.SpeechToText _speech;
  bool _isListening = false;
  String _text = 'Press the button and speak';

  @override
  void initState() {
    super.initState();
    _speech = stt.SpeechToText();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('Voice Recognition'),
      ),
      body: Column(
        children: [
          Expanded(
            child: Center(
              child: Text(
                _text,
                style: TextStyle(fontSize: 24.0),
              ),
            ),
          ),
          FloatingActionButton(
            onPressed: _listen,
            child: Icon(_isListening ? Icons.stop : Icons.mic),
          ),
        ],
      ),
    );
  }

  void _listen() async {
    if (!_isListening) {
      bool available = await _speech.initialize();
      if (available) {
        setState(() => _isListening = true);
        _speech.listen(
          onResult: (result) => setState(() {
            _text = result.recognizedWords;
          }),
        );
      }
    } else {
      setState(() => _isListening = false);
      _speech.stop();
    }
  }
}
```
This code creates a Flutter app with a microphone button that captures voice commands and updates the `_text` variable.

Firebase Code (Back-end):

Next, you need to create a Firebase Cloud Function that receives the voice command from the Flutter app and sends it to the Arduino board for processing. Here's an example code that shows how to create a Firebase Cloud Function that listens to changes in the Firebase Realtime Database and sends the voice command to the Arduino board using the Firebase Arduino library:
```javascript
const admin = require('firebase-admin');
const firebaseArduino = require('firebase-arduino');

admin.initializeApp();
firebaseArduino.initializeApp(admin);

exports.processVoiceCommand = functions.database
  .ref('/voiceCommand')
  .onWrite((change, context) => {
    const command = change.after.val();
    console.log(`Received voice command: ${command}`);
    firebaseArduino.sendData({ command });
    return null;
  });
```
This code listens to changes in the `/voiceCommand` path in the Firebase Realtime Database and sends the voice command to the Arduino board using the `firebaseArduino.sendData` function.

